const JARDIN_SRC = "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<title>L'Éclaircie — le plan du jardin<\/title>\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<style>\n:root{\n  --nuit:#0a0d10; --nuit2:#11161b; --trait:#2a3138;\n  --or:#d9a441; --or-pale:#f0d9a0; --creme:#e9e0cc;\n  --vert:#7fb069; --vert-clair:#a8d18a; --vert-sombre:#3d5a3a;\n  --orange:#ec9006; --orange-pale:#ffd79a;\n  --bleu:#0081B3; --bleu-clair:#4fb8e0; --bleu-nuit:#004572;\n  --paille:#c9a86a;\n  --texte:#c8c2b4; --texte-2:#8a8578; --texte-3:#5d594f;\n  --serif:\"Cambria\",\"Georgia\",\"Palatino Linotype\",serif;\n  --sans:\"Inter\",\"Segoe UI\",\"Helvetica Neue\",system-ui,sans-serif;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%;background:var(--nuit);color:var(--texte);font-family:var(--sans)}\n#page{display:flex;height:100vh;overflow:hidden}\n#scene{flex:1;min-width:0;display:flex;flex-direction:column;padding:20px 20px 12px}\n#tete{flex:none}\n#tete h1{margin:0;font-family:var(--serif);font-size:23px;font-weight:400;\n  letter-spacing:.05em;color:var(--creme)}\n#tete .ss{margin-top:5px;font-size:12px;color:var(--texte-3);letter-spacing:.04em}\n#barre{display:flex;gap:8px;margin:12px 0 2px;flex-wrap:wrap;align-items:center;\n  min-height:32px}\n.pl{background:#141a20;border:1px solid var(--trait);color:var(--texte-2);\n  border-radius:999px;padding:7px 15px;font:inherit;font-size:12.5px;cursor:pointer;\n  transition:.16s;letter-spacing:.02em}\n.pl:hover{border-color:#3d4750;color:var(--texte)}\n.pl.on{background:#1d2630;border-color:var(--or);color:var(--or-pale)}\n.pl b{font-weight:600;letter-spacing:.14em;margin-right:7px;color:var(--or);opacity:.8}\n.pl.on b{opacity:1}\n#reseaux{display:none;gap:7px;margin:8px 0 0;flex-wrap:wrap;align-items:center}\n#reseaux.vu{display:flex}\n#reseaux .lab{margin:0 6px 0 0;padding:0;border:0;font-size:10px;letter-spacing:.2em;\n  text-transform:uppercase;color:var(--texte-3)}\n.rz{background:#12181e;border:1px solid var(--trait);color:var(--texte-2);\n  border-radius:999px;padding:5px 13px;font:inherit;font-size:12px;cursor:pointer;\n  transition:.16s}\n.rz:hover{border-color:#3d4750;color:var(--texte)}\n.rz.on{background:#182028;border-color:var(--paille);color:var(--paille)}\n#rejouer{margin-left:auto;background:#101c24;border:1px solid #1d4257;color:var(--bleu-clair);\n  border-radius:999px;padding:7px 15px;font:inherit;font-size:12.5px;cursor:pointer;\n  display:none;transition:.16s;letter-spacing:.02em}\n#rejouer:hover{border-color:var(--bleu);background:#12242f}\n#rejouer.vu{display:block}\n#cadre{flex:1;min-height:0;position:relative;display:flex;margin-top:4px}\nsvg{flex:1;min-height:0;width:100%}\n#flotte{\n  position:absolute;pointer-events:none;z-index:5;padding:5px 11px;\n  background:rgba(10,13,16,.92);border:1px solid var(--or);border-radius:3px;\n  font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--or-pale);\n  opacity:0;transition:opacity .14s;white-space:nowrap;\n  transform:translate(-50%,-190%);\n}\n#flotte.on{opacity:1}\n#legende{flex:none;display:flex;gap:16px;flex-wrap:wrap;font-size:11px;\n  color:var(--texte-3);padding-top:8px;border-top:1px solid var(--trait);margin-top:4px}\n#legende span{display:flex;align-items:center;gap:6px}\n#legende i{width:11px;height:11px;border-radius:2px;display:inline-block}\n\naside{width:400px;flex:none;background:var(--nuit2);border-left:1px solid var(--trait);\n  overflow-y:auto;padding:24px 26px 40px}\naside h2{font-family:var(--serif);font-weight:400;font-size:21px;color:var(--creme);\n  margin:0 0 3px;letter-spacing:.02em}\naside .sur{font-size:11px;letter-spacing:.22em;text-transform:uppercase;\n  color:var(--or);opacity:.75;margin-bottom:14px}\naside p{font-size:13.5px;line-height:1.72;color:var(--texte-2);margin:0 0 13px}\naside b{color:var(--creme);font-weight:600}\naside em{color:var(--or-pale);font-style:italic}\n.puce{display:flex;gap:10px;margin:11px 0;font-size:12.5px;line-height:1.62;color:var(--texte-2)}\n.puce i{color:var(--or);font-style:normal;flex:none;opacity:.7}\n.lab{font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:var(--texte-3);\n  margin:24px 0 10px;padding-top:15px;border-top:1px solid var(--trait)}\n.fiche{background:#0d1216;border:1px solid #24313a;border-left:2px solid var(--or);\n  border-radius:6px;padding:15px 16px;margin:0 0 18px}\n.fiche h3{margin:0 0 7px;font-family:var(--serif);font-weight:400;font-size:16px;color:var(--or-pale)}\n.fiche .kind{font-size:10px;letter-spacing:.2em;text-transform:uppercase;\n  color:var(--texte-3);margin-bottom:8px}\n.fiche p{margin:0;font-size:12.8px;line-height:1.65}\n.rien{color:var(--texte-3);font-size:12px;font-style:italic}\n\n/* ------------------------------- le dessin ------------------------------- */\n.mur{fill:none;stroke:var(--creme);stroke-width:3.4;opacity:.55;stroke-linejoin:round}\n.mur-in{fill:#0e1512;stroke:none}\n.parc{fill:none;stroke:var(--texte-3);stroke-width:.8;opacity:.45;stroke-dasharray:2 5}\n.allee{fill:none;stroke:#2b332c;stroke-width:7;stroke-linecap:round;stroke-linejoin:round}\n.allee-b{fill:none;stroke:#3b4a3a;stroke-width:1;opacity:.5;stroke-linecap:round}\n.sentier{fill:none;stroke:#39412f;stroke-width:3.4;stroke-linecap:round;\n  stroke-dasharray:1.5 6;opacity:.85}\n\n/* A peine plus verte que le reste : elle n'est pas cloturee, elle est\n   juste le morceau qu'on n'a pas bati. */\n.etendue{fill:#0f1714;stroke:none}\n.pre{fill:#152418;stroke:#3d5a3a;stroke-width:1.1;stroke-dasharray:6 4}\n.enclos{fill:#1a1d15;stroke:#6d7a52;stroke-width:1.1;stroke-dasharray:4 3}\n.eau{fill:#0d2130;stroke:none}\n.margelle{fill:none;stroke:var(--bleu);stroke-width:2.4;opacity:.85}\n.clos{fill:#15181c;stroke:#8d6c7a;stroke-width:1.1}\n.sport{fill:#161d1a;stroke:#4a5f4a;stroke-width:1.1}\n\n/* La surbrillance doit se voir de l'autre bout de la piece : la forme\n   s'allume en plein, comme dans le plan de la ruche. */\n.zone{cursor:pointer}\n.zone:hover .pre,.zone:hover .enclos,.zone.on .pre,.zone.on .enclos{\n  stroke:var(--or);stroke-width:2.2;stroke-dasharray:none;fill:rgba(217,164,65,.13)}\n.zone:hover .etendue,.zone.on .etendue{stroke:var(--or);stroke-width:2.4;\n  fill:rgba(217,164,65,.07)}\n.zone:hover .eau,.zone.on .eau{fill:#16384e}\n.zone:hover .margelle,.zone.on .margelle{stroke:var(--or-pale);stroke-width:3.2}\n.zone:hover .anneau,.zone.on .anneau{stroke:var(--or);stroke-width:6.4}\n.zone:hover .chemin,.zone.on .chemin{stroke:var(--or);stroke-width:4}\n.zone:hover .sport,.zone.on .sport{stroke:var(--or);stroke-width:2.2;\n  fill:rgba(217,164,65,.11)}\n\n.bat{fill:#171c22;stroke:var(--creme);stroke-width:1.2;opacity:.92;cursor:pointer;\n  transition:fill .12s,stroke-width .12s}\n.bat:hover,.bat.on{fill:#3a2c14;stroke:var(--or);stroke-width:2.6}\n.bat.soin{fill:#101a20;stroke:var(--bleu)}\n.bat.soin:hover{fill:#152430}\n.bat.fin{fill:#1a1216;stroke:#8d6c7a}\n.cour{fill:#241a1e;stroke:#8d6c7a;stroke-width:1}\n.hachure{stroke:#8d6c7a;stroke-width:.8;opacity:.55}\n.bat.commun{fill:#1b1a14;stroke:var(--or);opacity:.95}\n.bat.ferme{fill:#1c1710;stroke:var(--paille);opacity:.95}\n.cab{fill:#141a15;stroke:var(--vert-sombre);stroke-width:.9}\n.jeu{fill:#1e1a14;stroke:var(--orange);stroke-width:1;opacity:.9;cursor:pointer;\n  transition:fill .12s,stroke-width .12s}\n.jeu:hover,.jeu.on{fill:#3a2c14;stroke:var(--or);stroke-width:2.6}\n\n.arbre{fill:var(--vert-sombre);opacity:.44}\n.arbre2{fill:none;stroke:var(--vert);stroke-width:.7;opacity:.22}\n.grille{stroke:var(--or);stroke-width:2.6;stroke-linecap:round}\n.grille.cond{stroke:#6b4a3a;stroke-dasharray:3 3}\n.fresque{fill:none;stroke:var(--vert-clair);stroke-width:2.2;opacity:.35;\n  stroke-linecap:round;stroke-dasharray:14 7}\n.etiq{font-family:var(--sans);font-size:9.5px;fill:var(--texte-2);\n  letter-spacing:.1em;text-transform:uppercase;pointer-events:none}\n.etiq.gd{font-size:11px;fill:var(--creme);letter-spacing:.26em}\n.etiq.hors{fill:var(--texte-3);text-transform:none;letter-spacing:.04em;font-size:9px}\n.etiq.paille{fill:var(--paille);opacity:.85}\n.note{font-family:var(--serif);font-size:10.5px;fill:var(--texte-3);\n  font-style:italic;letter-spacing:0;text-transform:none;pointer-events:none}\n\n.bete{fill:var(--creme);opacity:.62;pointer-events:none}\n.bete.paille{fill:var(--paille);opacity:.72}\n.chat{fill:#c9b8a0;opacity:.8;pointer-events:none}\n\n/* ------------------------------ ce qui bouge ------------------------------ */\n.onde{fill:none;stroke:var(--bleu-clair);stroke-width:1.1;opacity:0;\n  transform-box:fill-box;transform-origin:center;animation:onde 5.5s ease-out infinite}\n@keyframes onde{\n  0%{transform:scale(.12);opacity:0}\n  12%{opacity:.55}\n  100%{transform:scale(1);opacity:0}\n}\n.surface{fill:none;stroke:var(--bleu-clair);stroke-width:1;opacity:.3;\n  stroke-dasharray:5 9;animation:derive 14s linear infinite}\n@keyframes derive{to{stroke-dashoffset:-140}}\n/* Les chemins de l'etendue sont en sable tasse, pas en pointille : ce sont\n   de vrais chemins qu'on prend. L'anneau est plus large que les autres --\n   c'est celui que les petits font a velo. */\n.chemin{fill:none;stroke:#93825e;stroke-width:4.4;stroke-linecap:round;\n  stroke-linejoin:round;opacity:.92}\n.chemin-fond{fill:none;stroke:#201c14;stroke-width:7;stroke-linecap:round;\n  stroke-linejoin:round}\n.anneau{fill:none;stroke:#6d5f47;stroke-width:7;stroke-linecap:round;\n  stroke-linejoin:round;opacity:.6}\n.anneau-fond{fill:none;stroke:#1b1913;stroke-width:9.4;stroke-linecap:round;\n  stroke-linejoin:round;opacity:.55}\n.anneau-grain{fill:none;stroke:#9c8a68;stroke-width:7;stroke-linecap:butt;\n  stroke-dasharray:.7 4.6;opacity:.2}\n/* Certains arbres respirent : une lueur douce qui enfle et retombe, et\n   jamais deux au meme moment. C'est ce qui empeche le plan d'etre mort. */\n.lueur{fill:var(--vert-clair);transform-box:fill-box;transform-origin:center;\n  animation:respirer 9s ease-in-out infinite}\n@keyframes respirer{\n  0%,100%{opacity:.045;transform:scale(.8)}\n  50%{opacity:.19;transform:scale(1.3)}\n}\n#g-trajet{display:none}\n#g-trajet.vu{display:block}\n.trajet{fill:none;stroke:var(--bleu);stroke-width:2.2;stroke-linecap:round;\n  stroke-linejoin:round;stroke-dasharray:7 5}\n.trajet-ombre{fill:none;stroke:var(--nuit);stroke-width:7;stroke-linecap:round;\n  stroke-linejoin:round;opacity:.85}\n.marcheur{fill:var(--bleu-clair);stroke:var(--nuit);stroke-width:1.3}\n.halo-m{fill:var(--bleu);opacity:.18;animation:battre 2.4s ease-in-out infinite}\n@keyframes battre{0%,100%{opacity:.18}50%{opacity:.05}}\n.feuille{animation:respire 9s ease-in-out infinite}\n@keyframes respire{0%,100%{opacity:.4}50%{opacity:.58}}\n@media (prefers-reduced-motion: reduce){\n  .onde,.surface,.halo-m,.feuille,.lueur{animation:none}\n  .onde{opacity:.28} .lueur{opacity:.1}\n}\n<\/style>\n<\/head>\n<body>\n<div id=\"page\">\n  <div id=\"scene\">\n    <div id=\"tete\">\n      <h1>Le jardin<\/h1>\n      <div class=\"ss\">Le mur, l'étendue, les bêtes, les chemins. <b style=\"color:var(--texte-2)\">Cliquez n'importe quoi.<\/b><\/div>\n      <div id=\"barre\"><\/div>\n    <\/div>\n    <div id=\"cadre\"><svg id=\"svg\" viewBox=\"0 0 1020 700\" preserveAspectRatio=\"xMidYMid meet\"><\/svg>\n      <div id=\"flotte\"><\/div><\/div>\n    <div id=\"legende\"><\/div>\n  <\/div>\n  <aside><div id=\"pan\"><\/div><\/aside>\n<\/div>\n\n<script>\nconst SVG='http://www.w3.org/2000/svg', svg=document.getElementById('svg');\nconst el=(n,a={},p=svg)=>{const e=document.createElementNS(SVG,n);\n  for(const k in a) e.setAttribute(k,a[k]); p.appendChild(e); return e;};\nconst n2=v=>Math.round(v*10)/10;\n\n/* Un tirage reproductible : le plan doit etre le meme a chaque ouverture. */\nlet graine=20260819;\nconst alea=()=>{graine=(graine*1103515245+12345)&0x7fffffff; return graine/0x7fffffff;};\n\n/* Une enceinte n'est jamais droite : elle suit la rue. */\nconst lisse=(pts,f=.42)=>{\n  /* On demarre la ou la boucle finira, sinon le Z refermait par un segment\n     droit qui depassait du trace -- la queue vue en haut a gauche du mur. */\n  const d0=[pts[0][0]+(pts[1][0]-pts[0][0])*f, pts[0][1]+(pts[1][1]-pts[0][1])*f];\n  let d=`M${n2(d0[0])},${n2(d0[1])}`;\n  for(let i=0;i<pts.length;i++){\n    const a=pts[i], b=pts[(i+1)%pts.length], c=pts[(i+2)%pts.length];\n    const m1=[a[0]+(b[0]-a[0])*(1-f),a[1]+(b[1]-a[1])*(1-f)];\n    const m2=[b[0]+(c[0]-b[0])*f,b[1]+(c[1]-b[1])*f];\n    d+=` L${n2(m1[0])},${n2(m1[1])} Q${n2(b[0])},${n2(b[1])} ${n2(m2[0])},${n2(m2[1])}`;\n  }\n  return d+'Z';\n};\nconst poly=pts=>`M${pts.map(p=>n2(p[0])+','+n2(p[1])).join(' L')}`;\n/* Meme arrondi que lisse(), mais sur un chemin qui ne se referme pas. */\nconst lisseOuvert=(pts,f=.42)=>{\n  if(pts.length<3) return poly(pts);\n  let d=`M${n2(pts[0][0])},${n2(pts[0][1])}`;\n  for(let i=1;i<pts.length-1;i++){\n    const a=pts[i-1], b=pts[i], c=pts[i+1];\n    const m1=[a[0]+(b[0]-a[0])*(1-f), a[1]+(b[1]-a[1])*(1-f)];\n    const m2=[b[0]+(c[0]-b[0])*f,     b[1]+(c[1]-b[1])*f];\n    d+=` L${n2(m1[0])},${n2(m1[1])} Q${n2(b[0])},${n2(b[1])} ${n2(m2[0])},${n2(m2[1])}`;\n  }\n  const z=pts[pts.length-1];\n  return d+` L${n2(z[0])},${n2(z[1])}`;\n};\nconst boucle=pts=>poly(pts)+' Z';\n/* Rien de ce qui pousse n'est rectangulaire. Une tache fermee, irreguliere\n   mais reproductible : meme graine, meme contour a chaque ouverture. */\nconst tache=(cx,cy,rx,ry,n=11,irr=.17,gr=null)=>{\n  /* Une forme qui a sa graine ne depend plus de ce qui a ete dessine avant\n     elle. Sans ca, ajouter un arbre quelque part deformait la mare. */\n  const sauve=graine;\n  if(gr!==null) graine=gr;\n  const p=[];\n  for(let i=0;i<n;i++){\n    const a=i/n*Math.PI*2, k=1-irr+alea()*irr*2;\n    p.push([cx+Math.cos(a)*rx*k, cy+Math.sin(a)*ry*k]);\n  }\n  if(gr!==null) graine=sauve;\n  return lisse(p,.5);\n};\nconst dilate=(pts,d)=>{\n  const cx=pts.reduce((s,p)=>s+p[0],0)/pts.length, cy=pts.reduce((s,p)=>s+p[1],0)/pts.length;\n  return pts.map(([x,y])=>{const dx=x-cx,dy=y-cy,l=Math.hypot(dx,dy)||1;\n    return [x+dx/l*d, y+dy/l*d];});\n};\nconst dedans=(pts,[x,y])=>{\n  let d=false;\n  for(let i=0,j=pts.length-1;i<pts.length;j=i++){\n    const [xi,yi]=pts[i],[xj,yj]=pts[j];\n    if((yi>y)!==(yj>y) && x<(xj-xi)*(y-yi)/(yj-yi)+xi) d=!d;\n  }\n  return d;\n};\nconst centre=pts=>[pts.reduce((s,p)=>s+p[0],0)/pts.length, pts.reduce((s,p)=>s+p[1],0)/pts.length];\nfunction surLeTour(pts,t){\n  const n=pts.length, f=t*n, i=Math.floor(f)%n, r=f-Math.floor(f);\n  const a=pts[i], b=pts[(i+1)%n];\n  return [a[0]+(b[0]-a[0])*r, a[1]+(b[1]-a[1])*r];\n}\n\n/* =====================================================================\n   LES BETES — des silhouettes, pas des dessins\n   ===================================================================== */\nconst trait=(d,g,s,couleur='var(--creme)',w=1,o=.5)=>el('path',{d,transform:`scale(${s})`,\n  style:`stroke:${couleur};stroke-width:${w};opacity:${o};fill:none;stroke-linecap:round`},g);\n\n/* Une tete de poney a quatorze pixels ne ressemble a rien. Un point de\n   couleur, si : on lit l'espece a la teinte, et le plan reste propre. */\nconst TEINTES={\n  poney:'#d9a441', chevre:'#e9e0cc', poule:'#ec9006',\n  lapin:'#a8d18a', cochon:'#d99a9a', chat:'#9fb4c9'\n};\nconst BETES={\n  toboggan:(g,s)=>trait('M2,14 L10,4 L13,4 M10,4 L10,14 M13,4 C15,7 15,11 13,14',g,s,'var(--orange)',1.3,.75),\n  balancoire:(g,s)=>trait('M3,14 L8,3 L13,14 M5.4,7 L5.4,13 M10.6,7 L10.6,13 M4.4,13 L6.4,13 M9.6,13 L11.6,13',g,s,'var(--orange)',1.2,.7),\n  ballon:(g,s)=>{\n    el('circle',{cx:8,cy:9,r:5.4,transform:`scale(${s})`,\n      style:'stroke:var(--vert-clair);stroke-width:1.2;opacity:.5;fill:none'},g);\n    trait('M8,3.6 L8,14.4 M2.8,7 L13.2,11 M2.8,11 L13.2,7',g,s,'var(--vert-clair)',.9,.35);\n  }\n};\nfunction bete(type,x,y,s=1,p=svg){\n  const t=TEINTES[type];\n  if(t){\n    const g=el('g',{transform:`translate(${n2(x)},${n2(y)})`},p);\n    el('circle',{cx:0,cy:0,r:n2(5.4*s),fill:t,opacity:.13},g);\n    el('circle',{cx:0,cy:0,r:n2(3.1*s),fill:t,opacity:.9},g);\n    return g;\n  }\n  const g=el('g',{transform:`translate(${n2(x)},${n2(y)}) translate(-8,-9)`},p);\n  (BETES[type]||(()=>{}))(g,s);\n  return g;\n}\n\n/* =====================================================================\n   LES TROIS PLANS\n   ===================================================================== */\nconst PLANS=[\n{\n cle:'C', nom:'La fermette', sous:'une deuxième ville dans la ville',\n mur:[[150,86],[520,52],[900,96],[946,300],[906,560],[560,650],[190,616],[80,330]],\n principe:`<p><b>Au milieu, on a laissé le terrain tranquille.<\/b> Une mare, des bouts de prés,\n  des enclos, quelques cabanes. <em>C'est l'étendue, et c'est le mot qu'emploient les petits.<\/em><\/p>\n  <p><b>Le grand chemin en fait le tour, et deux routes la traversent.<\/b> C'est lui qui\n  délimite l'étendue du reste du jardin. <em>Il est plus large que tous les autres, parce que\n  c'est celui qu'on fait à vélo.<\/em><\/p>\n  <p><b>On y va parce qu'on veut y aller, ou on la traverse juste :<\/b> tout dépend du chemin\n  qu'on prend. <em>Et ça revient au même pour ceux qui vous attendent de l'autre côté.<\/em><\/p>\n  <p style=\"color:var(--texte-3)\">Six cents mètres dans la plus grande largeur.\n  <b>On met du temps à traverser le jardin, et le plan doit le dire.<\/b><\/p>`,\n enjeu:`<p><b>Le centre médical est à l'est, contre sa propre grille<\/b>, et la section 0\n  juste derrière. <em>Ce sont deux bâtiments du jardin comme les autres : on y va, on en revient,\n  et les petits savent très bien où ils sont.<\/em><\/p>\n  <p><b>Le jardin n'a pas été laissé à lui-même : il a été aménagé.<\/b> <em>Les dortoirs se\n  ressemblent, les allées sont régulières, le grand chemin fait un ovale presque parfait —\n  c'est un établissement, et ça se voit.<\/em> Ce qui vit, au milieu, c'est l'étendue.<\/p>`,\n defauts:[\n  ['La grille du sud ne s\\'ouvre plus','La chaîne est passée deux fois et le pêne a blanchi. L\\'herbe monte à travers, des deux côtés, à la même hauteur.'],\n  ['Les deux derniers dortoirs sont plus grands','Bâtis trente ans après les autres. Fenêtres plus hautes, crépi d\\'une autre teinte, et tout le monde le sait.'],\n  ['La fresque s\\'arrête au gymnase','On l\\'a adossé au mur bien plus tard. Les dessins reprennent de l\\'autre côté, en plus petit.'],\n  ['Un sentier contre la margelle','Personne ne l\\'a tracé. À force de longer l\\'eau pour regarder dedans, l\\'herbe n\\'a pas repoussé.']],\n grilles:[[115,208,'nord-ouest',0],[700,74,'principale',0],[934,380,'est',0],[330,628,'sud-ouest',0],[560,646,'sud',1]],\n etendue:[468,388,180,140],\n /* L'anneau : le tour de l'etendue, plus large que le reste. C'est celui\n    que les petits font a velo. */\n anneau:[[468,236],[556,250],[624,286],[656,340],[652,410],[616,470],[548,514],[468,530],[386,516],[320,478],[286,418],[292,348],[334,286],[398,250]],\n /* Deux chemins la traversent pour de bon, et se croisent pres de la mare. */\n routes:[\n  {de:`nord-ouest`,a:`est`,pts:[[115,208],[177,272],[189,299],[207,305],[225,323],[249,323],[273,335],[327,389],[333,404],[492,404],[516,392],[606,386],[648,365],[729,365],[747,383],[934,380]]},\n  {de:`sud-ouest`,a:`principale`,pts:[[330,628],[366,593],[366,584],[375,569],[375,545],[393,524],[393,488],[402,479],[405,446],[441,410],[462,404],[468,278],[489,278],[510,260],[549,257],[567,239],[627,239],[645,224],[651,224],[675,197],[675,152],[681,146],[681,113],[700,74]]}],\n trajet:{pts:[[115,208],[188,300],[274,336],[292,348],[286,418],[320,478],[386,516],[468,530],[548,514],[616,470],[652,410],[682,386],[706,372],[800,376],[836,370]]},\n eau:[385,350,56,40],\n pres:[\n  [546,328,56,42,'Le pré des poneys','poney',3],\n  [538,444,50,34,'Le pré des chèvres','chevre',4]],\n encl:[\n  [466,486,36,22,'Les poules','poule',4],\n  [356,462,34,20,'Les petites bêtes',['lapin','lapin','cochon','cochon'],4]],\n chats:[[.05,1],[.42,-1],[.71,1]],\n sport:[[330,92,152,74,'Le terrain']],\n bat:[\n  ['soin',766,254,152,104,'Centre médical','Le seul bâtiment à avoir un étage. Consultations au rez, dortoir de garde au premier, les dossiers au second. Le parking est devant, la grille de service à trente mètres.',-4],\n  ['commun',504,102,150,64,'Réfectoire','Les repas arrivent de la ville en camion, deux fois par jour. On les réchauffe ici, on ne les fait pas. Les œufs, eux, viennent du poulailler.',3],\n  ['commun',227,507,124,64,'Gymnase','Adossé au mur, ce qui coupe la fresque. Sol souple, filets aux fenêtres, une odeur qui ne part jamais.',-6],\n  ['commun',694,182,112,60,'Salle de jeu','Pour les jours de pluie, et il pleut souvent. Le parquet est marqué aux endroits où les tables reviennent toujours.',5],\n  ['ferme',584,296,34,22,'L\\'écurie','Quatre boxes, une sellerie, du foin jusqu\\'au plafond. Elle est dans l\\'étendue, accolée au pré : les poneys y rentrent seuls le soir, et l\\'un d\\'eux sait ouvrir le loquet.',4],\n  ['ferme',416,450,36,18,'Le poulailler','Une cabane sur pilotis, une échelle, une trappe. Ce sont les petits qui ramassent, et il y a un tableau à la porte pour dire qui ramasse quand.',16],\n  ['ferme',352,472,32,16,'Le clapier','Les lapins et les cochons d\\'Inde ensemble : deux étages de clapiers, du grillage fin, des tuyaux enterrés dans l\\'enclos. On ferme le soir à cause des chats.',3],\n  ['ferme',400,268,54,22,'L\\'abri','Un toit sur quatre poteaux, de la paille au sol, ouvert sur trois côtés. C\\'est là que les bêtes vont quand il pleut, et les petits avec elles. Personne ne les en empêche.',-4],\n  ['ferme',500,406,44,22,'La cabane','Le foin, les seaux, les brosses, les bottes en trois tailles. Ça sent la paille mouillée toute l\\'année.',-5],\n  ['ferme',322,424,52,22,'Le local technique','Contre la margelle, à moitié enterré. La pompe et le filtre de la mare. Un bâtiment que personne ne regarde et sans lequel l\\'eau serait verte en deux semaines.',-9],\n  ['bat',196,120,100,52,'Dortoirs 1','Vingt petits, quatre berceurs, un salon commun et une buanderie. Les fenêtres du bas ont des barreaux ronds peints en jaune.',-5],\n  ['bat',323,185,100,52,'Dortoirs 2','',4],\n  ['bat',544,167,100,52,'Dortoirs 3','',-3],\n  ['bat',760,120,100,52,'Dortoirs 4','',7],\n  ['bat',146,330,96,52,'Dortoirs 5','',3],\n  ['bat',160,432,96,52,'Dortoirs 6','',-4],\n  ['bat',406,562,100,52,'Dortoirs 7','',5],\n  ['bat',548,556,100,52,'Dortoirs 8','',-6],\n  ['bat',670,508,106,56,'Dortoirs 9','Bâti trente ans après les autres, avec le 8. Plus grand, fenêtres plus hautes, crépi d\\'une autre teinte.',8],\n  ['cab',700,256,46,26,'Cabanon',''],\n  ['cab',706,316,46,26,'Garage','']],\n jeux:[[196,214,92,62,'Aire de jeu','toboggan'],[810,180,92,58,'Aire de jeu','balancoire'],[700,104,58,46,'Bacs à sable','']],\n fresques:[[[160,100],[500,66]],[[540,62],[890,110]],[[928,340],[900,540]],[[850,590],[220,606]]],\n /* Ils prennent l'allee du nord-ouest, puis la grande allee par le sud,\n    puis l'allee de service. Ils ne coupent a travers rien. */\n /* La section 0 : un batiment rond et une petite cour au milieu. */\n soleil:[840,428,44,'Section 0','<b>Le bâtiment soleil<\/b>, et c\\'est le seul nom que les petits emploient : ils voient un soleil dans sa forme, et personne ne les a jamais contredits. <em>Le registre, lui, dit section 0 — zéro comme l\\'âge.<\/em> Un plan rond, une petite cour plantée au milieu qu\\'on ne voit que d\\'en haut, six chambres et une véranda tout autour. <b>On y accompagne ceux qui arrivent à zéro, et ça n\\'a rien de caché<\/b> : c\\'est un bâtiment du jardin comme les autres.'],\n echelle:[104,676],\n etiq:[[700,60,'','entrée principale']]\n}];\n\n/* les fiches des lieux qui ne sont pas des bâtiments */\nconst LIEUX={\n \"L'étendue\":['le milieu du jardin',\"Tout l'espace qu'on n'a pas bâti : la mare, les prés, les enclos, les cabanes. <b>L'allée n'y entre pas — elle en fait le tour.<\/b> Un chemin, lui, y entre exprès, passe devant chaque bête et ressort au même endroit. <em>On ne traverse pas l'étendue pour aller ailleurs. On y va pour y être.<\/em>\"],\n \"La mare\":[\"au milieu de l'étendue\",\"Une margelle montée à hauteur de poitrine tout autour, assez large pour qu'on s'y accoude et trop haute pour qu'on l'enjambe. <b>Personne n'est jamais tombé dedans<\/b>, et deux berceurs sont là en permanence quand il y a du monde. <em>Il y a des poissons, et personne ne sait qui les a mis.<\/em>\"],\n \"Le grand chemin\":[\"il délimite l'étendue\",\"<b>C'est lui qui sépare l'étendue du reste du jardin<\/b>, et il en fait le tour en entier. Plus large que tous les autres, et c'est fait exprès : <b>on le fait à vélo, et dans les deux sens.<\/b> <em>Il y a un record, il n'est écrit nulle part, et tout le monde le connaît.<\/em>\"],\n \"Les chemins de l'étendue\":[\"dedans\",\"<b>Ils la traversent pour de bon.<\/b> On peut couper par le milieu quand on va quelque part, ou tourner autour de la mare parce qu'on n'a rien de mieux à faire. <em>Tout dépend du chemin qu'on prend, et ça revient au même pour ceux qui vous attendent.<\/em> Sable tassé, refait deux fois par an.\"],\n \"Le pré des poneys\":[\"l'étendue, à l'est\",\"Trois poneys, jamais plus grands qu'un double poney. <b>C'est une règle : au jardin, aucune bête ne doit dépasser celui qui la caresse.<\/b> <em>Ils sont doux, lents, et complètement blasés.<\/em>\"],\n \"Le pré des chèvres\":[\"l'étendue, au sud-est\",\"Quatre chèvres naines, un tas de rochers monté exprès pour qu'elles grimpent dessus, et un portillon que les petits savent ouvrir. <em>Elles mangent tout ce qui dépasse, y compris les manches.<\/em>\"],\n \"Les poules\":[\"l'étendue, au sud\",\"Cinq poules et un tableau à la porte pour dire qui ramasse quand. <b>Les œufs partent au réfectoire, et ça compte beaucoup dans l'idée qu'on se fait de soi à cinq ans.<\/b>\"],\n \"Les petites bêtes\":[\"l'étendue, à l'ouest\",\"Les lapins et les cochons d'Inde ensemble, dans un enclos plus grand qu'il n'en faut, avec des tuyaux enterrés pour qu'ils aient où disparaître. <b>C'est le seul enclos où l'on entre.<\/b> <em>Les cochons d'Inde tiennent dans deux mains et ils sifflent dès qu'on approche du bac de granulés.<\/em>\"],\n \"Le terrain\":['au nord',\"Bitume peint, deux paniers à hauteur d'enfant, des buts tracés dessus. <em>Les lignes du milieu ont été repeintes tant de fois qu'il y en a trois qui se chevauchent.<\/em>\"],\n \"Aire de jeu\":['dans les zones ouvertes',\"Toboggan, balançoires, structures en bois. <b>Il y en a plusieurs, exprès, pour qu'aucun dortoir ne soit plus loin qu'un autre.<\/b>\"],\n \"Bacs à sable\":['près du réfectoire',\"Deux bacs, une bâche qu'on tire le soir, et du sable qu'on remplace tous les deux ans.\"],\n \"Le trajet\":['une scène à écrire',\"Andrew et Isaac entrent par la grille du nord-ouest et vont au centre médical, à l'est. <b>Ils traversent tout le jardin : une dizaine de minutes à pied, d'un pas décidé.<\/b> <em>Le chemin passe au sud de l'étendue, ce qui leur fait longer les prés — et c'est là qu'on peut leur faire voir ce qu'on veut leur faire voir.<\/em>\"],\n \"Les fresques\":[\"le mur, côté cour\",\"<b>De l'extérieur le mur est nu — du crépi crème, pas une ouverture.<\/b> De ce côté-ci il est peint sur toute sa longueur, et par ceux qui vivent là. <em>Ça se refait, ça se recouvre, et personne ne garde trace de ce qu'il y avait avant.<\/em> Les fresques s'arrêtent net là où l'on a bâti contre le mur, et reprennent de l'autre côté, en plus petit.\"],\n \"Les chats\":['partout',\"Personne ne les a fait venir. Ils entrent par le mur, dorment sur les bancs chauds, se laissent porter par ceux qui savent s'y prendre. <b>Il y en a trois, et leurs noms ne sont les mêmes dans aucun dortoir.<\/b> <em>Ils vont où ils veulent, et c'est bien la seule chose qui soit vraie de bout en bout dans ce monde.<\/em>\"]\n};\n\n/* =====================================================================\n   RENDU\n   ===================================================================== */\nlet courant=0, choisi=null, anim=null;\nconst sortirClasses=()=>[].forEach.call(svg.querySelectorAll('.on'),e=>e.classList.remove('on'));\nfunction choisir(nom,genre,txt,noeud){\n  choisi=[nom,genre,txt]; sortirClasses();\n  if(noeud) noeud.classList.add('on');\n  rendPan();\n}\nconst flotte=document.getElementById('flotte');\nconst cadre=document.getElementById('cadre');\nfunction cliquable(g,nom,genre,txt,cible){\n  g.addEventListener('click',e=>{e.stopPropagation(); choisir(nom,genre,txt,cible||g);});\n  g.addEventListener('mouseenter',()=>{flotte.textContent=nom; flotte.classList.add('on');});\n  g.addEventListener('mouseleave',()=>flotte.classList.remove('on'));\n  g.addEventListener('mousemove',e=>{\n    const r=cadre.getBoundingClientRect();\n    flotte.style.left=(e.clientX-r.left)+'px';\n    flotte.style.top=(e.clientY-r.top)+'px';\n  });\n}\n\nfunction dessine(p){\n  if(anim){cancelAnimationFrame(anim); anim=null;}\n  svg.innerHTML=''; graine=20260819;\n  const cH=el('g'), cB=el('g'), cA=el('g'), cE=el('g');\n\n  /* ---- le parc, dehors ---- */\n  const dehors=dilate(p.mur,30), loin=dilate(p.mur,52);\n  el('path',{d:lisse(loin),class:'parc'},cH);\n  el('path',{d:lisse(dehors),class:'parc'},cH);\n  for(let i=0;i<64;i++){\n    const q=surLeTour(dehors,i/64), o=surLeTour(loin,i/64);\n    if(i%4===0) el('circle',{cx:n2(o[0]),cy:n2(o[1]),r:n2(4+alea()*3),class:'arbre'},cH);\n    if(i%8===3) el('line',{x1:n2(q[0]-3),y1:n2(q[1]),x2:n2(q[0]+3),y2:n2(q[1]),\n      stroke:'#4a5148','stroke-width':1.6,'stroke-linecap':'round'},cH);\n  }\n\n  /* ---- le mur et ses fresques ---- */\n  el('path',{d:lisse(p.mur),class:'mur-in'},cB);\n  const murPath=el('path',{d:lisse(p.mur),class:'mur'},cB);\n  const c0=centre(p.mur);\n  /* Ou passe le mur, et dans quel sens il va, a l'endroit qu'on lui demande.\n     Le rayon depuis le centre ne suffit pas : sur une courbe il tombe de\n     travers, et les portes avec lui. */\n  const Lmur=murPath.getTotalLength();\n  function surLeMur(x,y){\n    let best=0, bd=Infinity;\n    for(let i=0;i<=900;i++){\n      const t=Lmur*i/900, q=murPath.getPointAtLength(t);\n      const d=(q.x-x)*(q.x-x)+(q.y-y)*(q.y-y);\n      if(d<bd){ bd=d; best=t; }\n    }\n    const q=murPath.getPointAtLength(best);\n    const a=murPath.getPointAtLength((best-3+Lmur)%Lmur);\n    const b=murPath.getPointAtLength((best+3)%Lmur);\n    let tx=b.x-a.x, ty=b.y-a.y;\n    const l=Math.hypot(tx,ty)||1; tx/=l; ty/=l;\n    /* la normale, tournee vers le dehors */\n    let nx=-ty, ny=tx;\n    if((q.x+nx-c0[0])**2+(q.y+ny-c0[1])**2 < (q.x-nx-c0[0])**2+(q.y-ny-c0[1])**2){\n      nx=-nx; ny=-ny;\n    }\n    return {x:q.x, y:q.y, tx, ty, nx, ny};\n  }\n  /* ---- les grilles ---- */\n  (p.grilles||[]).forEach(([x,y,nom,cond])=>{\n    const m=surLeMur(x,y), w=cond?11:17;\n    /* le vantail, dans l'axe du mur */\n    el('line',{x1:n2(m.x-m.tx*w),y1:n2(m.y-m.ty*w),x2:n2(m.x+m.tx*w),y2:n2(m.y+m.ty*w),\n      class:'grille'+(cond?' cond':'')},cB);\n    /* les barreaux, en travers */\n    for(let k=-2;k<=2;k++){\n      const bx=m.x+m.tx*k*w/2.6, by=m.y+m.ty*k*w/2.6;\n      el('line',{x1:n2(bx-m.nx*6),y1:n2(by-m.ny*6),x2:n2(bx+m.nx*6),y2:n2(by+m.ny*6),\n        stroke:cond?'#6b4a3a':'var(--or)','stroke-width':.8,opacity:.6},cB);\n    }\n    el('text',{x:n2(m.x+m.nx*24),y:n2(m.y+m.ny*24+3),class:'etiq hors',\n      'text-anchor':'middle'},cE).textContent=nom;\n  });\n\n  /* ---- les zones plates ---- */\n\n  /* ======================= L'ÉTENDUE ======================= */\n  if(p.etendue){\n    const [ex,ey,erx,ery]=p.etendue;\n    const ge=el('g',{class:'zone'},cB);\n    /* Pas de contour a elle : c'est la grande allee qui la delimite. */\n    el('path',{d:lisse(p.anneau,.48),class:'etendue'},ge);\n    cliquable(ge,\"L'étendue\",LIEUX[\"L'étendue\"][0],LIEUX[\"L'étendue\"][1]);\n\n    /* L'herbe, avant tout le reste : elle passe dessous. */\n    if(p.anneau){\n      const d=lisse(p.anneau,.48);\n      const ga=el('g',{class:'zone'},cB);\n      el('path',{d,class:'anneau-fond'},ga);\n      el('path',{d,class:'anneau','data-voie':'le grand chemin'},ga);\n      el('path',{d,class:'anneau-grain'},ga);   /* le gravier */\n      cliquable(ga,\"Le grand chemin\",LIEUX[\"Le grand chemin\"][0],LIEUX[\"Le grand chemin\"][1]);\n    }\n\n\n    const poser=(liste,cls)=>(liste||[]).forEach(([x,y,rx,ry,nom,type,n],rang)=>{\n      const g=el('g',{class:'zone'},cB);\n      el('path',{d:tache(x,y,rx,ry,10,.12,3300000+rang*97001+(cls==='pre'?11:57)),class:cls},g);\n      const types = Array.isArray(type) ? type : new Array(n).fill(type);\n      for(let i=0;i<types.length;i++){\n        const a=alea()*Math.PI*2, k=.2+alea()*.55;\n        bete(types[i], x+Math.cos(a)*rx*k, y+Math.sin(a)*ry*k, cls==='pre'?1.05:.85, g);\n      }\n      el('text',{x:n2(x),y:n2(y+ry+12),class:'etiq paille','text-anchor':'middle'},cE)\n        .textContent=nom;\n      const f=LIEUX[nom]||[\"l'étendue\",''];\n      cliquable(g,nom,f[0],f[1]);\n    });\n    poser(p.pres,'pre');\n    poser(p.encl,'enclos');\n\n\n    if(p.eau){\n      const [mx,my,mrx,mry]=p.eau;\n      const gm=el('g',{class:'zone'},cB);\n      /* Ecrite a la main, une fois pour toutes : c'est la silhouette que\n         l'autrice a retenue, et elle ne doit plus jamais changer. */\n      const CONTOUR=[[-1.00,-.12],[-.86,-.52],[-.52,-.80],[-.10,-.92],[.30,-.86],\n        [.62,-.62],[.86,-.30],[1.00,.06],[.88,.42],[.58,.66],[.20,.74],\n        [-.14,.62],[-.34,.34],[-.62,.30],[-.88,.14]];\n      const d=lisse(CONTOUR.map(([u,v])=>[mx+u*mrx, my+v*mry]),.5);\n      el('path',{d,class:'eau'},gm);\n      /* La ride vient du meme contour, reduit : elle ne peut plus sortir. */\n      el('path',{d:lisse(CONTOUR.map(([u,v])=>[mx+u*mrx*.62, my+v*mry*.58]),.5),\n        class:'surface'},gm);\n      el('path',{d,class:'margelle'},gm);\n      [[mx-18,my-8,0],[mx+16,my+9,1.9],[mx+2,my-16,3.6]].forEach(([x,y,r])=>{\n        const o=el('circle',{cx:n2(x),cy:n2(y),r:14,class:'onde'},gm);\n        o.style.animationDelay=r+'s';\n      });\n      el('text',{x:n2(mx-38),y:n2(my-mry-9),class:'etiq','text-anchor':'middle'},cE)\n        .textContent='La mare';\n      cliquable(gm,'La mare',LIEUX['La mare'][0],LIEUX['La mare'][1]);\n    }\n  }\n\n  /* ---- les routes du reseau choisi : chacune va d'une porte a une autre ---- */\n  if(p.routes){\n    p.routes.forEach(r=>{\n      const d=lisseOuvert(r.pts,.3);\n      const g=el('g',{class:'zone'},cB);\n      el('path',{d,class:'chemin-fond'},g);\n      el('path',{d,class:'chemin','data-voie':'de la grille '+r.de+' à la grille '+r.a},g);\n      cliquable(g,'La route '+r.de+' — '+r.a,'une porte à une autre',\n        \"Elle part d'une grille et elle arrive à une autre, sans interruption. \"\n        +\"<b>On la prend pour aller quelque part, pas pour se promener<\/b> — \"\n        +\"<em>la grande allée, elle, est là pour se promener.<\/em>\");\n    });\n  }\n  (p.allees||[]).forEach((a,i)=>{\n    el('path',{d:poly(a),class:'allee','data-voie':'allée '+(i+1)},cB);\n    el('path',{d:poly(a),class:'allee-b'},cB);});\n  (p.sentiers||[]).forEach(a=>el('path',{d:poly(a),class:'sentier'},cB));\n\n  /* ---- les arbres ---- */\n  const occupe=(p.bat||[]).map(b=>[b[1]-6,b[2]-6,b[3]+12,b[4]+12])\n    .concat((p.jeux||[]).map(j=>[j[0]-6,j[1]-6,j[2]+12,j[3]+12]))\n    .concat((p.sport||[]).map(j=>[j[0]-6,j[1]-6,j[2]+12,j[3]+12]));\n  /* Il y a des arbres partout, l'etendue comprise : c'est le meme jardin.\n     On ne les met que dans les pres et les enclos -- une bete a besoin\n     d'herbe, pas d'ombre, et son ombre elle l'a dans son abri. */\n  const zonesBetes=(p.pres||[]).concat(p.encl||[]);\n  let pose=0;\n  for(let i=0;i<2400 && pose<148;i++){\n    const x=80+alea()*880, y=50+alea()*610;\n    if(!dedans(p.mur,[x,y])) continue;\n    if(occupe.some(([a,b,w,h])=>x>a&&x<a+w&&y>b&&y<b+h)) continue;\n    if(p.eau && Math.pow((x-p.eau[0])/(p.eau[2]+11),2)\n               +Math.pow((y-p.eau[1])/(p.eau[3]+11),2) < 1) continue;\n    if(zonesBetes.some(([zx,zy,zrx,zry])=>\n      Math.pow((x-zx)/(zrx+9),2)+Math.pow((y-zy)/(zry+9),2) < 1)) continue;\n    const r=3.2+alea()*4.4;\n    /* Un arbre sur trois respire, et jamais au meme moment que son voisin. */\n    if(alea()>.66){\n      const l=el('circle',{cx:n2(x),cy:n2(y),r:n2(r+7),class:'lueur'},cB);\n      l.style.animationDelay=n2(-alea()*9)+'s';\n      l.style.animationDuration=n2(7+alea()*6)+'s';\n    }\n    const c=el('circle',{cx:n2(x),cy:n2(y),r:n2(r),class:'arbre'},cB);\n    if(alea()>.6){ c.classList.add('feuille'); c.style.animationDelay=n2(-alea()*9)+'s'; }\n    if(alea()>.62) el('circle',{cx:n2(x),cy:n2(y),r:n2(r+3),class:'arbre2'},cB);\n    pose++;\n  }\n\n  /* ---- le terrain de sport ---- */\n  (p.sport||[]).forEach(([x,y,w,h,nom])=>{\n    const g=el('g',{class:'zone'},cB);\n    el('rect',{x,y,width:w,height:h,rx:h/2,class:'sport'},g);\n    el('line',{x1:n2(x+w/2),y1:y,x2:n2(x+w/2),y2:n2(y+h),\n      stroke:'var(--creme)','stroke-width':.8,opacity:.3},g);\n    el('circle',{cx:n2(x+w/2),cy:n2(y+h/2),r:n2(h/5),fill:'none',\n      stroke:'var(--creme)','stroke-width':.8,opacity:.3},g);\n    bete('ballon',x+w-24,y+h-20,.9,g);\n    el('text',{x:n2(x+w/2),y:n2(y+h+13),class:'etiq','text-anchor':'middle'},cE).textContent=nom;\n    const f=LIEUX[nom]||['au jardin',''];\n    cliquable(g,nom,f[0],f[1]);\n  });\n\n  /* ---- les aires de jeu ---- */\n  (p.jeux||[]).forEach(([x,y,w,h,t,icone])=>{\n    const g=el('g',{},cB);\n    const r=el('rect',{x,y,width:w,height:h,rx:9,class:'jeu'},g);\n    for(let i=0;i<4;i++)\n      el('circle',{cx:n2(x+10+alea()*(w-20)),cy:n2(y+10+alea()*(h-20)),\n        r:n2(2+alea()*3),fill:'var(--orange)',opacity:.35},g);\n    if(icone) bete(icone,x+w/2,y+h/2-1,1.15,g);\n    el('text',{x:n2(x+w/2),y:n2(y+h+12),class:'etiq','text-anchor':'middle'},cE).textContent=t;\n    const f=LIEUX[t]||['au jardin',''];\n    cliquable(g,t,f[0],f[1],r);\n    g.addEventListener('mouseenter',()=>{flotte.textContent=t; flotte.classList.add('on');});\n  });\n\n  /* ---- les creux ---- */\n  (p.trous||[]).forEach(([x,y,r,t])=>{\n    if(!r) return;\n    el('ellipse',{cx:x,cy:y,rx:r,ry:n2(r*.62),fill:'#16241c',stroke:'#2f4634',\n      'stroke-width':.9,'stroke-dasharray':'4 4'},cB);\n    if(t) el('text',{x,y:n2(y+r*.62+13),class:'note','text-anchor':'middle'},cE).textContent=t;\n  });\n\n  /* ---- le trajet ---- */\n  let chemin=null, gTraj=null;\n  if(p.trajet){\n    gTraj=el('g',{id:'g-trajet'},cB);\n    const dt=lisseOuvert(p.trajet.pts,.28);\n    el('path',{d:dt,class:'trajet-ombre'},gTraj);\n    chemin=el('path',{d:dt,class:'trajet','data-voie':'le trajet d\\'Andrew'},gTraj);\n    const a=p.trajet.pts[0], z=p.trajet.pts[p.trajet.pts.length-1];\n    [a,z].forEach(q=>el('circle',{cx:n2(q[0]),cy:n2(q[1]),r:4.6,fill:'var(--bleu)',\n      stroke:'var(--nuit)','stroke-width':1.4},gTraj));\n  }\n\n  /* ---- l'échelle ---- */\n  if(p.echelle){\n    const [x,y]=p.echelle, L=145;\n    el('line',{x1:x,y1:y,x2:n2(x+L),y2:y,stroke:'var(--texte-3)','stroke-width':1.4},cE);\n    [0,L].forEach(d=>el('line',{x1:n2(x+d),y1:n2(y-4),x2:n2(x+d),y2:n2(y+4),\n      stroke:'var(--texte-3)','stroke-width':1.4},cE));\n    el('text',{x:n2(x+L/2),y:n2(y-9),class:'etiq hors','text-anchor':'middle'},cE)\n      .textContent='100 mètres';\n  }\n\n  /* ---- la section 0, le batiment soleil ---- */\n  if(p.soleil){\n    const [sx,sy,sr,snom,stxt]=p.soleil;\n    const g=el('g',{},cB);\n    const TAU=Math.PI*2, N=7;                 /* six chambres et la veranda */\n    const R=sr, ri=sr*.54, rc=sr*.30;\n    /* Large a la base, etroit a la pointe : c'est ce qui fait le rayon.\n       L'inverse donne des palettes, pas un soleil. */\n    const gap=TAU/N*.45, tip=TAU/N*.14;\n    const pt=(a,r)=>[sx+Math.cos(a)*r, sy+Math.sin(a)*r];\n    const trace=q=>q.map((v,i)=>(i?'L':'M')+n2(v[0])+','+n2(v[1])).join(' ')+'Z';\n\n    /* le corps : un anneau, et sept ailes qui s'evasent */\n    let corps=[];\n    for(let i=0;i<N;i++){\n      const a=-Math.PI/2 + i*TAU/N;\n      corps.push(pt(a-gap,ri), pt(a-tip,R), pt(a+tip,R), pt(a+gap,ri));\n    }\n    /* la cour, au milieu */\n    const cour=[];\n    for(let i=0;i<8;i++) cour.push(pt(i/8*TAU + Math.PI/8, rc));\n\n    const mur=el('path',{d:trace(corps)+' '+trace(cour),'fill-rule':'evenodd',\n      class:'bat fin','data-nom':snom},g);\n    mur.style.cursor='pointer';\n\n    /* la cour est hachuree : c'est ce qui la distingue d'un trou */\n    const cl=el('clipPath',{id:'cour-0'},g);\n    el('path',{d:trace(cour)},cl);\n    const gh=el('g',{'clip-path':'url(#cour-0)'},g);\n    for(let k=-8;k<=8;k++)\n      el('line',{x1:n2(sx-rc*1.4+k*4),y1:n2(sy-rc*1.4),\n                 x2:n2(sx+rc*1.4+k*4),y2:n2(sy+rc*1.4),class:'hachure'},gh);\n    el('path',{d:trace(cour),fill:'none',stroke:'#8d6c7a','stroke-width':1,\n      opacity:.8},g);\n\n    el('text',{x:n2(sx),y:n2(sy+R+15),class:'etiq','text-anchor':'middle'},cE)\n      .textContent=snom;\n    cliquable(g,snom,'le b\\u00e2timent soleil',stxt,mur);\n  }\n\n  /* ---- le bâti ---- */\n  (p.bat||[]).forEach(b=>{\n    const [cls,x,y,w,h,t,txt,biais]=b;\n    const petit = cls==='cab';\n    const a=el('rect',{x,y,width:w,height:h,rx:petit?3:5,\n      class:petit?'cab':'bat '+(cls==='bat'?'':cls),'data-nom':t},cB);\n    const ang = biais===1 ? -11 : biais;\n    if(biais) a.setAttribute('transform',`rotate(${ang} ${n2(x+w/2)} ${n2(y+h/2)})`);\n    if(!petit){\n      a.style.cursor='pointer';\n      const genre = cls==='soin'?'le soin':cls==='fin'?'le bâtiment soleil':\n                    cls==='ferme'?'la fermette':cls==='commun'?'bâtiment commun':'les dortoirs';\n      cliquable(a,t,genre,txt,a);\n    }\n    const dedansAutre = cls==='fin' && (p.bat||[]).some(o=>o[0]==='soin'\n      && x>o[1] && y>o[2] && x+w<o[1]+o[3] && y+h<o[2]+o[4]);\n    /* Les batiments de la fermette sont petits : leur nom se pose dessous,\n       a l'horizontale. Tourner une etiquette de trente pixels ne la rend pas\n       lisible, ca la rend seulement tournee. */\n    const dessous = dedansAutre || cls==='ferme' || petit;\n    const px=x+w/2, py=dessous ? y+h+11 : y+h/2+3;\n    const e=el('text',{x:n2(px),y:n2(py),\n      class:'etiq'+(cls==='ferme'?' paille':''),'text-anchor':'middle'},cE);\n    e.textContent=t;\n    if(w<70 && !dessous) e.setAttribute('transform',`rotate(-90 ${n2(px)} ${n2(py)})`);\n    else if(biais && !dessous) e.setAttribute('transform',`rotate(${ang} ${n2(px)} ${n2(py)})`);\n  });\n\n  if(p.etendue) el('text',{x:n2(p.etendue[0]),y:n2(p.etendue[1]-p.etendue[3]+16),\n    class:'etiq gd','text-anchor':'middle'},cE).textContent=\"L'ÉTENDUE\";\n  (p.etiq||[]).forEach(([x,y,cls,t])=>{\n    if(!t) return;\n    el('text',{x,y,class:'etiq '+(cls||''),'text-anchor':'middle'},cE).textContent=t;\n  });\n\n  /* ======================= CE QUI BOUGE ======================= */\n  const mobiles=[];\n\n  /* Les chats n'ont pas d'itineraire. Ils marchent, ils tournent quand\n     l'envie leur prend, et le mur les fait revenir. */\n  if(p.chats){\n    /* Ou un chat peut poser une patte : dans l'enceinte, hors du bati, et\n       pas dans la mare. Le reste du jardin lui appartient. */\n    const murs=(p.bat||[]).map(o=>[o[1]-3,o[2]-3,o[3]+6,o[4]+6])\n      .concat((p.jeux||[]).map(o=>[o[0],o[1],o[2],o[3]]));\n    /* Le mur dessine est le trace lisse, qui rentre a l'interieur des\n       angles du polygone. On teste donc la forme, pas les points. */\n    const enceinte=el('path',{d:lisse(dilate(p.mur,-14)),fill:'none',stroke:'none'},cA);\n    const pt=svg.createSVGPoint();\n    const libre=(x,y)=>{\n      pt.x=x; pt.y=y;\n      if(!enceinte.isPointInFill(pt)) return false;\n      if(murs.some(([a2,b2,w,h])=>x>a2&&x<a2+w&&y>b2&&y<b2+h)) return false;\n      if(p.eau){\n        const [mx,my,mrx,mry]=p.eau;\n        if(Math.pow((x-mx)/(mrx+3),2)+Math.pow((y-my)/(mry+3),2) < 1) return false;\n      }\n      /* Un chat ne va pas se promener chez les poules. Enfin, celui-ci non. */\n      for(const [zx,zy,zrx,zry] of (p.pres||[]).concat(p.encl||[]))\n        if(Math.pow((x-zx)/(zrx+4),2)+Math.pow((y-zy)/(zry+4),2) < 1) return false;\n      return true;\n    };\n    p.chats.forEach(()=>{\n      const g=el('g',{style:'cursor:pointer;pointer-events:auto'},cA);\n      bete('chat',0,0,.92,g);\n      g.addEventListener('click',e=>{e.stopPropagation();\n        choisir('Les chats',LIEUX['Les chats'][0],LIEUX['Les chats'][1],null);});\n      let x=c0[0], y=c0[1];\n      for(let i=0;i<400;i++){\n        const px=110+alea()*800, py=90+alea()*500;\n        if(libre(px,py)){ x=px; y=py; break; }\n      }\n      let cap=alea()*Math.PI*2, pause=0, coince=0;\n      mobiles.push({tick:(dt)=>{\n        if(pause>0){ pause-=dt; return; }\n        if(alea()<0.004){ pause=600+alea()*2400; return; }\n        cap += (alea()-.5)*0.11;\n        const v=0.021*dt;\n        const nx=x+Math.cos(cap)*v, ny=y+Math.sin(cap)*v;\n        if(libre(nx,ny)){ x=nx; y=ny; coince=0; }\n        else {\n          /* Il bute : il tourne, comme il ferait. Et s'il tourne en rond,\n             il finit par faire demi-tour franchement. */\n          cap += (++coince>7) ? Math.PI : Math.PI*(0.35+alea()*0.5);\n          coince = coince>7 ? 0 : coince;\n        }\n        g.setAttribute('transform',\n          `translate(${n2(x)},${n2(y)}) scale(${Math.cos(cap)<0?-1:1},1)`);\n      }});\n    });\n  }\n\n  const bouton=document.getElementById('rejouer');\n  bouton.className = chemin ? 'vu' : '';\n  bouton.textContent = '▸ le trajet d\\'Andrew et Isaac';\n  if(chemin){\n    const L=chemin.getTotalLength();\n    const halo=el('circle',{r:9,class:'halo-m',cx:-99,cy:-99},cA);\n    const m1=el('circle',{r:5,class:'marcheur',cx:-99,cy:-99},cA);\n    const m2=el('circle',{r:4.2,class:'marcheur',cx:-99,cy:-99},cA);\n    const lab=el('text',{class:'note',x:-99,y:-99,'text-anchor':'middle',\n      style:'fill:var(--bleu-clair)'},cA);\n    let t=null;\n    bouton.onclick=()=>{\n      if(gTraj.classList.contains('vu') && t===null){\n        gTraj.classList.remove('vu');\n        bouton.textContent='▸ le trajet d\\'Andrew et Isaac';\n        return;\n      }\n      gTraj.classList.add('vu');\n      bouton.textContent='× masquer le trajet';\n      t=0; chemin.style.strokeDasharray=L; chemin.style.strokeDashoffset=L;\n      choisir('Le trajet',LIEUX['Le trajet'][0],LIEUX['Le trajet'][1],null);\n    };\n    mobiles.push({tick:(dt)=>{\n      if(t===null) return;\n      t+=dt*0.00011;\n      if(t>=1.14){ t=null;\n        chemin.style.strokeDasharray='7 5'; chemin.style.strokeDashoffset=0;\n        [halo,m1,m2].forEach(e=>{e.setAttribute('cx',-99);e.setAttribute('cy',-99);});\n        lab.textContent=''; return; }\n      const u=Math.min(t,1);\n      chemin.style.strokeDashoffset=L*(1-u);\n      const a=chemin.getPointAtLength(L*u), b=chemin.getPointAtLength(Math.max(0,L*u-13));\n      [[halo,a],[m1,a],[m2,b]].forEach(([e,q])=>{\n        e.setAttribute('cx',n2(q.x)); e.setAttribute('cy',n2(q.y));});\n      lab.setAttribute('x',n2(a.x)); lab.setAttribute('y',n2(a.y-14));\n      lab.textContent = u<.45 ? 'Andrew et Isaac' : (u<.95 ? '' : 'le centre médical');\n    }});\n  }\n\n  if(mobiles.length){\n    let prec=null;\n    const pas=(ts)=>{\n      const dt=prec===null?16:Math.min(60,ts-prec); prec=ts;\n      mobiles.forEach(m=>{\n        if(m.tick){ m.tick(dt); return; }\n        m.t=(m.t+m.v*dt*m.sens+1)%1;\n        const q=m.ch.getPointAtLength(m.L*m.t);\n        const r=m.ch.getPointAtLength(m.L*((m.t+0.004)%1));\n        const sens=(r.x-q.x)*m.sens>=0?1:-1;\n        m.g.setAttribute('transform',`translate(${n2(q.x)},${n2(q.y)}) scale(${sens},1)`);\n      });\n      anim=requestAnimationFrame(pas);\n    };\n    anim=requestAnimationFrame(pas);\n  }\n\n  svg.addEventListener('click',()=>{choisi=null; sortirClasses(); rendPan();});\n  legende(p);\n}\n\nfunction legende(p){\n  const L=[['#171c22','#e9e0cc','dortoirs'],['#1b1a14','#d9a441','bâtiments communs'],\n    ['#1c1710','#c9a86a','la fermette'],['#101a20','#0081B3','centre médical'],\n    ['#1a1216','#8d6c7a','la section 0'],['#1e1a14','#ec9006','aires de jeu'],\n    ['#0d2130','#0081B3','la mare'],['#152418','#3d5a3a','prés et enclos']];\n  document.getElementById('legende').innerHTML =\n    L.map(([f,b,t])=>`<span><i style=\"background:${f};border:1px solid ${b}\"><\/i>${t}<\/span>`).join('')\n    + [['#d9a441','poneys'],['#e9e0cc','chèvres'],['#ec9006','poules'],\n       ['#a8d18a','lapins'],['#d99a9a','cochons d\\'Inde'],['#9fb4c9','chats']]\n       .map(([c,t])=>`<span><i style=\"background:${c};border-radius:50%;width:9px;height:9px\"><\/i>${t}<\/span>`).join('')\n    + `<span><i style=\"background:none;border-top:3px solid #8a7350\"><\/i>le grand chemin<\/span>`\n    + `<span><i style=\"background:none;border-top:2px solid #93825e\"><\/i>les routes, d'une porte à une autre<\/span>`\n    + `<span style=\"color:var(--texte-2)\">— cliquez n'importe quoi<\/span>`;\n}\n\nfunction rendPan(){\n  const p=PLANS[courant];\n  let h='';\n  if(choisi){\n    h+=`<div class=\"fiche\"><div class=\"kind\">${choisi[1]||''}<\/div><h3>${choisi[0]}<\/h3>\n        <p>${choisi[2] || `Rien de particulier — et c'est bien le but : la plupart des bâtiments d'un jardin sont interchangeables.`}<\/p><\/div>`;\n  }\n  h+=`<div class=\"sur\">${p.nom}<\/div>\n    <p style=\"color:var(--texte-3);font-size:12px;margin-top:-6px\">${p.sous}<\/p>`;\n  h+=`${p.principe}\n    <div class=\"lab\">Ce que ce plan décide<\/div>${p.enjeu}`;\n  if(p.defauts && p.defauts.length){\n    h+=`<div class=\"lab\">Ce qui ne va pas, et qui doit rester<\/div>`;\n    p.defauts.forEach(([t,d])=>{h+=`<div class=\"puce\"><i>◦<\/i><span><b>${t}.<\/b> ${d}<\/span><\/div>`;});\n  }\n  if(!choisi) h+=`<div class=\"lab\">Le détail<\/div><p class=\"rien\">Cliquez un bâtiment, un enclos, la mare, un chemin, un chat.<\/p>`;\n  document.getElementById('pan').innerHTML=h;\n  document.querySelector('aside').scrollTop=0;\n}\n\nconst rej=document.createElement('button');\nrej.id='rejouer'; barre.appendChild(rej);\n\ndessine(PLANS[courant]); rendPan();\n<\/script>\n<\/body>\n<\/html>\n";

(function(){
  const b = document.querySelector('.rail-btn[data-vue="jardin"]');
  const v = document.getElementById('v-jardin');
  if(!b || !v) return;
  let pose = false;
  /* On ne fabrique la page qu'au premier clic : l'atelier s'ouvre en une
     seconde et le plan ne coute rien tant que personne ne le regarde. */
  b.addEventListener('click', () => {
    if(pose) return; pose = true;
    const f = document.createElement('iframe');
    f.title = 'Le plan du jardin';
    f.setAttribute('loading','lazy');
    f.srcdoc = JARDIN_SRC;
    v.appendChild(f);
  });
})();
